import "forge-std/Test.sol";
import "../src/0xbebbfe5b549f5db6e6c78ca97cac19d1fb03082c.sol";

contract VaultProxyTest is Test {
    VaultProxy vaultProxy;
    address owner = address(0x1);
    address attacker = address(0x2);
    uint256 initialOwnerSlotValue;

    function setUp() public {
        vm.deal(owner, 1 ether);
        vm.prank(owner, owner);
        vaultProxy = new VaultProxy{value: 1 ether}();
    }

    function testVerifyOwnerUnderflow() public {
        // Record initial owner slot value
        bytes32 ownerSlot = bytes32(uint256(0));
        initialOwnerSlotValue = uint256(vm.load(address(vaultProxy), ownerSlot));

        // Verify that Owner is the valid address
        assertEq(address(uint160(initialOwnerSlotValue)), owner, "Initial owner not properly set");

        // Transfer to attacker to trigger owner slot underflow in modifier
        vm.prank(owner);
        vaultProxy.transferOwner(attacker);

        // Verify underflow by checking new owner value
        bytes32 attackerSlot = bytes32(uint256(0));
        uint256 currentOwnerValue = uint256(vm.load(address(vaultProxy), attackerSlot));

        // Validate the new owner address matches the attacker address
        assertEq(address(uint160(currentOwnerValue)), attacker, "New owner should be the attacker address");

        // Verify slot value is a valid address (non-zero)
        assertTrue(currentOwnerValue != 0, "Owner slot should never be zero");
    }
}
